import path from "path";
import * as glob from "glob";
import {
  composeStories,
  setProjectAnnotations,
  type Meta,
  type StoryFn,
} from "@storybook/react";
import { describe, test, expect } from "@jest/globals";
import "jest-specific-snapshot";
import { render } from "@testing-library/react";

type StoryFile = {
  default: Meta;
  [name: string]: StoryFn | Meta;
};

const compose = (
  entry: StoryFile
): ReturnType<typeof composeStories<StoryFile>> => {
  try {
    return composeStories(entry);
  } catch (e) {
    throw new Error(
      `There was an issue composing stories for the module: ${JSON.stringify(
        entry
      )}, ${e}`
    );
  }
};

function getAllStoryFiles() {
  const storyFiles = glob.sync(
    path.resolve(__dirname, "../src/components/**/*.stories.tsx")
  );

  return storyFiles.map((filePath) => {
    const storyDir = path.dirname(filePath);
    const storyFile = require(filePath);
    const componentName = path
      .basename(filePath)
      .replace(/\.(stories|story)\.[^/.]+$/, "");
    return { filePath, storyDir, componentName, storyFile };
  });
}

// Recreate similar options to Storyshots. Place your configuration below
const options = {
  // suite: "Storybook Tests",
  suite: "Storyshots",
  storyKindRegex: /^.*?DontTest$/,
  storyNameRegex: /UNSET/,
  snapshotsDirName: "__snapshots__",
  snapshotExtension: ".storyshot", //to keep up with old naming
};

setProjectAnnotations({
  testingLibraryRender: render,
});

jest.mock("react", () => ({
  ...jest.requireActual("react"),
  useId: () => "useid-mock",
}));
jest.useFakeTimers({
  now: new Date(2021, 5, 22),
});

describe(options.suite, () => {
  getAllStoryFiles().forEach(({ storyFile, componentName, storyDir }) => {
    const meta = storyFile.default;
    const title = meta.title || componentName;

    if (
      options.storyKindRegex.test(title) ||
      meta.parameters?.storyshots?.disable
    ) {
      // Skip component tests if they are disabled
      return;
    }
    afterEach(() => {
      // without this, storyshots at the end has just the blank screen
      document.body.innerHTML = "";
    });

    describe(title, () => {
      const stories = Object.entries(compose(storyFile))
        .map(([name, story]) => ({ name, story }))
        .filter(({ name, story }) => {
          // Implements a filtering mechanism to avoid running stories that are disabled via parameters or that match a specific regex mirroring the default behavior of Storyshots.
          return (
            !options.storyNameRegex.test(name) &&
            !story.parameters.storyshots?.disable
          );
        });

      if (stories.length <= 0) {
        throw new Error(
          `No stories found for this module: ${title}. Make sure there is at least one valid story for this module, without a disable parameter, or add parameters.storyshots.disable in the default export of this file.`
        );
      }

      stories.forEach(({ name, story }) => {
        const testFn = story.tags.includes("skip-test") ? test.skip : test; //condition to skip test

        testFn(name, async () => {
          await story.run();
          // Ensures a consistent snapshot by waiting for the component to render by adding a delay of 1 ms before taking the snapshot.
          await new Promise((resolve) => setTimeout(resolve, 10));

          // Add a basic check to ensure component is mounted
          const element = document.body.firstChild;
          if (!element) {
            throw new Error(`Story "${name}" did not render any content`);
          }

          // Check if we got a preview message instead of actual content
          const isPreviewMessage = (element as HTMLElement).querySelector(
            "#a11y-status-message"
          );
          if (isPreviewMessage && isPreviewMessage.parentElement === element) {
            throw new Error(`Story "${name}" only rendered preview message`);
          }

          const snapshotPath = path.join(
            storyDir,
            options.snapshotsDirName,
            `${componentName}${options.snapshotExtension}`
          );

          // @ts-ignore
          expect(document.body.firstChild).toMatchSpecificSnapshot(
            snapshotPath
          );
        });
      });
    });
  });
});
